WITH base_bal AS (    SELECT CTACTB,            SUM(CASE WHEN REFERENCIA BETWEEN :VAR_DATA_INICIO AND :VAR_DATA_FIM THEN VLRLANC ELSE 0 END) AS soma_ate_atu,            SUM(CASE WHEN REFERENCIA BETWEEN DATE_SUB(:VAR_DATA_INICIO, INTERVAL 1 YEAR) AND DATE_SUB(:VAR_DATA_FIM, INTERVAL 1 YEAR) THEN VLRLANC ELSE 0 END) AS soma_ate_ant     FROM IMP_BASE_BALANCETE     WHERE CODEMP = :VAR_EMPRESA_DRE     GROUP BY CTACTB) SELECT DET.ORDEM,        DET.NOME_GRUPO,        SUM(IFNULL(B.soma_ate_atu, 0) * IFNULL(DETCTACTB.SINAL, 0)) AS ANO_ATUAL,        SUM(IFNULL(B.soma_ate_ant, 0) * IFNULL(DETCTACTB.SINAL, 0)) AS ANO_ANTERIOR FROM ESTR_DEMONSTRATIVOS EST INNER JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO INNER JOIN DET_DEMONSTRATIVO_REFERENCIA DETREF ON DET.ID = DETREF.ID_DET_DEMONSTRATIVO LEFT JOIN DET_DEMONSTRATIVO_CTACTB DETCTACTB ON DETREF.ID = DETCTACTB.ID_DET_DEMONSTRATIVO_REFERENCIA LEFT JOIN base_bal B ON B.CTACTB = DETCTACTB.PADRAO_CTACTB WHERE EST.ID = 2   AND DETREF.ANO_REFERENCIA = (      SELECT MAX(R.ANO_REFERENCIA)       FROM DET_DEMONSTRATIVO_REFERENCIA R       WHERE R.ID_DET_DEMONSTRATIVO = DET.ID         AND R.ANO_REFERENCIA <= YEAR(:VAR_DATA_FIM)  )GROUP BY DET.ORDEM, DET.NOME_GRUPO ORDER BY DET.ORDEM